bash -lc 'python3 - <<"PY" 
p = "/src/openexr/src/lib/OpenEXR/ImfHuf.cpp" 
text = open(p, "r", encoding="utf-8").read() 
if "readUIntBounded" not in text:
    anchor = "unsigned int\nreadUInt (const char buf[4])"
    pos = text.find(anchor)
    if pos == -1:
        print("ANCHOR_NOT_FOUND")
        raise SystemExit(1)
    insert = """
static inline unsigned int readUIntBounded (const char* p, const char* end)
{
    const unsigned char* b = (const unsigned char*) p;
    const unsigned char* e = (const unsigned char*) end;
    if (b + 3 < e) {
        return ((unsigned int) b[0]) | (((unsigned int) b[1]) << 8u) |
               (((unsigned int) b[2]) << 16u) | (((unsigned int) b[3]) << 24u);
    } else {
        return 0;
    }
}
"""
    text = text[:pos] + insert + text[pos:]
# patch call sites
text = text.replace("int im = readUInt (compressed);","int im = readUIntBounded (compressed, compressed + nCompressed);")
text = text.replace("int iM = readUInt (compressed + 4);","int iM = readUIntBounded (compressed + 4, compressed + nCompressed);")
text = text.replace("int nBits = readUInt (compressed + 12);","int nBits = readUIntBounded (compressed + 12, compressed + nCompressed);")
open(p, "w", encoding="utf-8").write(text)
print("Patched ImfHuf.cpp with readUIntBounded")
PY'
